-- assets where risk_score between 50 and 90 and not tag in (pci, "lab env") | stats median(risk_score) by criticality | sort criticality | limit 10
Median risk_score of assets where risk_score is between 50 and 90 and not (tag is one of pci, "lab env"), grouped by criticality, ordered by criticality ascending, first 10

SELECT (assets.criticality)::text AS c0, percentile_cont(0.5) WITHIN GROUP (ORDER BY assets.risk_score) AS c1 FROM assets WHERE assets.tenant_id = $1 AND NOT EXISTS (SELECT 1 FROM assets ph WHERE ph.id = assets.id AND ph.tenant_id = $3 AND ph.program_only AND EXISTS (SELECT 1 FROM asset_program_links pl JOIN bounty_programs pp ON pp.tenant_id = pl.tenant_id AND pp.id = pl.program_id WHERE pl.tenant_id = ph.tenant_id AND pl.asset_id = ph.id AND pp.visibility = 'private') AND NOT EXISTS (SELECT 1 FROM asset_program_links pl JOIN bounty_programs pp ON pp.tenant_id = pl.tenant_id AND pp.id = pl.program_id WHERE pl.tenant_id = ph.tenant_id AND pl.asset_id = ph.id AND NOT (pp.visibility = 'private' AND NOT EXISTS ( SELECT 1 FROM groups pg JOIN group_members pgm ON pgm.group_id = pg.id WHERE pg.tenant_id = pp.tenant_id AND pg.id = pp.group_id AND pg.is_active AND pgm.user_id = $2)))) AND (((assets.risk_score >= $4::bigint) AND (assets.risk_score <= $5::bigint) AND (NOT COALESCE((assets.tags && $6::text[]), FALSE))) AND ((NOT COALESCE((assets.deleted_at IS NOT NULL), FALSE)) AND (NOT COALESCE((assets.program_only), FALSE)))) GROUP BY 1 ORDER BY c0 ASC NULLS LAST LIMIT 11

